/// **Keys clang-format still accepts but no longer dumps** — so the table above cannot list them, and a document
/// that writes one is not an error in clang-format (measured: 22.1.3 formats this corpus happily while its
/// `.clang-format` sets `AllowAllConstructorInitializersOnNextLine`, which the dump never prints).
///
/// They are **parsed and not yet mapped**: `SpacesInParentheses` is `SpacesInParens` now, `SortIncludes` is an enum,
/// `DeriveLineEnding` and `UseCRLF` became `LineEnding`, and the rest are aliases of options that were renamed.
/// Accepting them keeps a document readable; mapping them is a separate step.
pub const PARSED_BUT_NOT_DUMPED: &[&str] = &[    "AlignConsecutiveAssignments",
    "AlignConsecutiveBitFields",
    "AlignConsecutiveDeclarations",
    "AlignConsecutiveMacros",
    "AlignTrailingComments",
    "AllowAllConstructorInitializersOnNextLine",
    "AlwaysBreakAfterReturnType",
    "AlwaysBreakTemplateDeclarations",
    "BreakBeforeInheritanceComma",
    "BreakConstructorInitializersBeforeComma",
    "ConstructorInitializerAllOnOneLineOrOnePerLine",
    "DeriveLineEnding",
    "IncludeCategories",
    "KeepEmptyLinesAtTheStartOfBlocks",
    "RawStringFormats",
    "SortIncludes",
    "SpaceBeforeParensOptions",
    "SpaceInEmptyParentheses",
    "SpacesInConditionalStatement",
    "SpacesInCStyleCastParentheses",
    "SpacesInLineCommentPrefix",
    "SpacesInParentheses",
    "UseCRLF",
];